(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["clinical-medicine-and-surgery-i-exam-5"]={"title":"Clinical Medicine and Surgery I Exam 5","sections":[{"id":"l26-emph","title":"★ Professor Emphasized — Virchow Triad & Wells Criteria","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l26-dvt","title":"Deep Vein Thrombosis","style":"--acc:#a3341f;--acc-bg:#f2e3e0;--acc-zebra:#f9f1ef;--acc-ink:#7f2918"},{"id":"l26-cvi","title":"Chronic Venous Insufficiency","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l26-varicose","title":"Varicose Veins","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l26-phlebitis","title":"Superficial Phlebitis, Thrombophlebitis & Septic Thrombophlebitis","style":"--acc:#1f5c3a;--acc-bg:#e0e8e3;--acc-zebra:#eff4f1;--acc-ink:#18482d"},{"id":"l26-avf","title":"Arteriovenous Fistula","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l27-pad","title":"Peripheral Artery Disease","style":"--acc:#7a2d5a;--acc-bg:#ece2e8;--acc-zebra:#f6f0f3;--acc-ink:#5f2346"},{"id":"l27-cli","title":"Critical Limb Ischemia & Acute Occlusion","style":"--acc:#a3341f;--acc-bg:#f2e3e0;--acc-zebra:#f9f1ef;--acc-ink:#7f2918"},{"id":"l27-carotid","title":"Carotid Artery Disease","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"},{"id":"l27-aorta","title":"Aneurysms & Dissection","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l28-emph","title":"★ Carter Emphasized — Cardiomyopathy","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l28-dcm","title":"Dilated Cardiomyopathy","style":"--acc:#5a3d8a;--acc-bg:#e8e4ef;--acc-zebra:#f3f1f7;--acc-ink:#46306c"},{"id":"l28-myo","title":"Myocarditis & Takotsubo","style":"--acc:#1f5c3a;--acc-bg:#e0e8e3;--acc-zebra:#eff4f1;--acc-ink:#18482d"},{"id":"l28-hcm","title":"Hypertrophic Cardiomyopathy","style":"--acc:#7a2d47;--acc-bg:#ece2e5;--acc-zebra:#f6f0f2;--acc-ink:#5f2337"},{"id":"l28-rcm","title":"Restrictive Cardiomyopathy & Populations","style":"--acc:#2f5d6b;--acc-bg:#e2e8ea;--acc-zebra:#f0f4f5;--acc-ink:#254953"}],"rows":[{"t":"★ Virchow triad","d":"Why a clot forms in a vein: <b>venous stasis</b> + <b>hypercoagulable state</b> + <b>endothelial trauma</b> (vascular endothelial injury). Three big overarching categories; she named all three three times in a row. Several arms often act together (a hip fracture is trauma, then immobilization).","s":0},{"t":"Stasis (alterations in blood flow)","d":"Immobilization: long flights, prolonged sitting, postoperative inactivity (the deck gives about a <b>20-fold</b> risk). Venous insufficiency. Heart failure.","s":0},{"t":"Hypercoagulable state","d":"Inherited: <b>factor V Leiden = the most common inherited cause</b>; prothrombin gene mutation; protein C or protein S deficiency; antithrombin deficiency. Acquired: cancer; oral contraceptive pill (more if she also smokes or is obese) or postmenopausal estrogen replacement therapy; pregnancy.","s":0},{"t":"Endothelial trauma","d":"Surgery, especially <b>knee or hip replacement</b> or hip fracture repair; trauma and burns; intravenous drug use (lower extremity injection). The slide also files smoking and hypertension here.","s":0},{"t":"Triad on a case","d":"Long car ride or a cast &rarr; stasis. Cancer, pregnancy, estrogen or a known clotting disorder &rarr; hypercoagulable state. Recent surgery, fracture, burns or injection drug use &rarr; endothelial trauma.","s":0},{"t":"★ Wells criteria: use","d":"Stratifies the pretest likelihood of deep vein thrombosis. <b>Outpatient and emergency department only &mdash; not inpatients.</b> She said the criteria come straight from the risk factors, so know the risk factors best.","s":0},{"t":"Wells: +1 each","d":"Active cancer (treatment or palliation within 6 months) &middot; bedridden more than 3 days or major surgery within 12 weeks &middot; calf swelling more than 3 cm versus the other leg (measured 10 cm below the tibial tuberosity) &middot; collateral (nonvaricose) superficial veins &middot; entire leg swollen &middot; localized tenderness along the deep venous system &middot; pitting edema confined to the symptomatic leg &middot; paralysis, paresis or recent plaster immobilization of the lower extremity &middot; previously documented deep vein thrombosis.","s":0},{"t":"Wells: &minus;2","d":"<b>Alternative diagnosis at least as likely as deep vein thrombosis = &minus;2.</b>","s":0},{"t":"Wells: score &rarr; order","d":"<b>Zero or less = low</b> &rarr; D-dimer first (negative: stop; positive: ultrasound). <b>1 to 2 = moderate</b> (pretest probability about 17%) &rarr; D-dimer, then ultrasound if positive. <b>3 or more = high</b> &rarr; <b>skip the D-dimer, order the ultrasound.</b>","s":0},{"t":"Wells: pathway","d":"Low or moderate: D-dimer negative = stop; positive = ultrasound of the thigh; negative = stop. High: ultrasound of the thigh; if negative, either ultrasound of the lower leg, phlebography (venography), or a repeat thigh ultrasound in <b>1 week</b>.","s":0},{"t":"Travel is NOT a criterion","d":"&ldquo;Bedridden&rdquo; means after surgery or immobilized in a cast or plaster, so a long flight scores nothing (travel is still a risk factor and a minor transient trigger for treatment duration).","s":0},{"t":"★ D-dimer","d":"<b>Sensitive but not specific.</b> A raised D-dimer means increased fibrinolysis somewhere, not necessarily a leg clot; a rule-out test for deep vein thrombosis and pulmonary embolism, only when the Wells score is low or moderate. Know what you will do next with either result. Contrast venography (gold standard, invasive) was replaced by venous duplex ultrasound.","s":0},{"t":"Epidemiology","d":"Clot in the deep veins, usually the legs; lower extremity about <b>10 times</b> more common than upper. Starts in the calf and moves proximally (popliteal, femoral, iliac). Proximal: femoral and popliteal; distal: <b>peroneal</b>; pregnancy: pelvic veins. Upper extremity 5&ndash;10% of all, from <b>pacemakers, implantable cardiac defibrillators, central venous catheters</b>. Pulmonary embolism: up to 6% upper vs <b>15&ndash;30%</b> lower.","s":1},{"t":"Other risk factors","d":"<b>★ Personal or family history of clot &mdash; prior episode about 30 times the recurrence risk.</b> Age older than 60; obesity; slightly more males; smoking, heart failure, hypertension, chronic kidney disease, chronic obstructive pulmonary disease, inflammatory bowel disease; cancer and chemotherapy; air travel and sedentary life; estrogen contraceptives, postmenopausal hormone replacement, first <b>6&ndash;12 weeks postpartum</b>.","s":1},{"t":"Presentation","d":"Swelling (<b>97%</b> sensitive), pain (86%), warmth (72%), &plusmn; erythema; a calf cramp that persists and worsens over days. Distal clot: calf only; proximal: calf or whole leg. <b>Homan sign</b> is neither sensitive nor specific. Upper extremity: arm swelling and discomfort.","s":1},{"t":"Differential","d":"Ruptured popliteal (Baker) cyst: severe sudden calf discomfort. Cellulitis: erythema, possibly fever and chills. Post-thrombotic syndrome: chronic venous insufficiency 6&ndash;24 months after a clot. Superficial thrombophlebitis: tender cord. Lymphedema: chronic edema, pelvic surgery, malignancy or radiation. Calf muscle tear: inciting injury, ankle bruising. Drug-induced edema (amlodipine): often bilateral, no inflammation.","s":1},{"t":"Diagnosis","d":"Wells score (top card), then D-dimer and/or <b>venous duplex ultrasound of the involved extremity</b>; say why you are ordering it.","s":1},{"t":"★ Treatment: mainstay","d":"<b>Anticoagulation is the mainstay &mdash; &ldquo;the biggest thing that we need to know.&rdquo;</b> Thrombolysis and thrombectomy are add-ons for selected large clots, never routine. Strategies: (1) heparin, then bridge to warfarin; (2) parenteral for <b>5 days</b>, then dabigatran or edoxaban; (3) oral monotherapy, loading then maintenance: rivaroxaban or apixaban.","s":1},{"t":"Anticoagulant classes","d":"Low molecular weight heparin: enoxaparin. Unfractionated heparin: intravenous bolus then infusion, adjusted by the activated partial thromboplastin time. Fondaparinux: indirect factor Xa inhibitor. Rivaroxaban, apixaban: direct factor Xa inhibitors. Dabigatran: direct thrombin inhibitor. Warfarin: vitamin K antagonist, monitored by the international normalized ratio.","s":1},{"t":"Contraindications","d":"<b>Active bleeding, acute intracranial hemorrhage, major trauma, severe bleeding disorders.</b>","s":1},{"t":"★ Duration","d":"Minimum <b>3 months</b> for every first episode. <b>Major transient (reversible) factor</b> (general anesthesia over 30 minutes, hospitalization or bed rest 3 days or more, major trauma or fracture): <b>3 months</b>. <b>Minor transient factor</b> (estrogen, pregnancy, minor surgery, prolonged travel, minor leg injury): <b>3&ndash;6 months</b>. <b>Unprovoked first clot: indefinite</b> (an undiscovered clotting condition cannot be excluded).","s":1},{"t":"★ Outpatient","d":"<b>Yes:</b> hemodynamically stable, low bleeding risk, no renal insufficiency, good support and reliable adherence. <b>No:</b> iliofemoral (proximal) clot, concurrent symptomatic pulmonary embolism, high bleeding risk, other comorbidities needing inpatient care. Options: rivaroxaban; apixaban; low molecular weight heparin or fondaparinux 5 days then dabigatran or edoxaban; or either heparin 5 days overlapping warfarin until the international normalized ratio is above 2. <b>Creatinine clearance below 30 mL/min: hospitalize</b>; unfractionated heparin + warfarin overlapped at least 5 days and until the ratio is above 2 for 24 hours.","s":1},{"t":"Reversal agents","d":"Unfractionated or low molecular weight heparin: <b>protamine sulfate</b>. Dabigatran: <b>idarucizumab</b>. Apixaban, rivaroxaban: <b>andexanet alfa</b>. Warfarin: four-factor prothrombin complex concentrate, fresh frozen plasma or intravenous vitamin K; oral vitamin K is the usual outpatient choice. Bleeding is the most serious adverse effect.","s":1},{"t":"Vena cava filter","d":"Inferior vena cava filter <b>only</b> with an acute proximal lower extremity clot and active bleeding, or when anticoagulation is otherwise contraindicated; keeps the clot from traveling to the lungs.","s":1},{"t":"Prevention","d":"<b>Intermittent pneumatic compression</b> (sequential compression devices), especially when immobilized after surgery or in a long hospital stay. It does the calf muscles&rsquo; job so blood does not stagnate: it treats the stasis arm of the triad.","s":1},{"t":"Complications","d":"<b>Pulmonary embolism = the biggest</b>: ask every patient about breathing difficulty right away. Post-thrombotic syndrome (chronic venous insufficiency, 6&ndash;24 months later). Recurrence. Bleeding from treatment. Fatal pulmonary embolism without adequate treatment: under 1% (clot alone), about 3% (non-massive), about 9% (massive).","s":1},{"t":"What","d":"Severe manifestation of venous hypertension (also <b>post-thrombotic syndrome</b>): edema, skin changes (hyperpigmentation, dermatitis, lipodermatosclerosis) and ulceration from reflux and/or obstruction. <b>Primary</b> = wall or valve abnormality; <b>secondary</b> = prior deep vein thrombosis.","s":2},{"t":"Causes","d":"<b>★ Prior deep vein thrombosis = the most common cause</b> (about 25% have no known clot; ask about leg trauma or surgery). Also progressive superficial venous reflux, pelvic vein obstruction, arteriovenous fistula. Risk factors: advancing age, female, family history, ligamentous laxity (flat feet), higher body mass index, smoking, leg trauma, higher parity, high estrogen states.","s":2},{"t":"Presentation","d":"<b>Progressive pitting edema of the lower leg</b> is the primary symptom. Dull discomfort, heaviness, throbbing, burning, pruritus from the <b>medial malleolus</b>; worse standing or sitting with feet dependent, <b>relieved by elevation and walking</b>. Grade and document the pitting.","s":2},{"t":"Skin findings","d":"<b>Stasis dermatitis</b>: pruritic, eczematous; earliest sign is erythema, scaling and slight hyperpigmentation above the medial malleolus. <b>Hemosiderin</b> staining: brown or blue-gray, separates venous from arterial. <b>Lipodermatosclerosis</b>: firm, indurated, skin tacked down, medial ankle, may form a constrictive band. Cellulitis: blanching erythema, hard to diagnose &mdash; outline and date it.","s":2},{"t":"Venous ulcer","d":"Above the ankle, <b>medial or anterior</b>; painful; clean base, fibrinous exudate, serous drainage. Heals with a thin scar that breaks down easily. Arterial ulcers: dry, punched out, painful at the toes and lateral ankle.","s":2},{"t":"Differential","d":"Heart failure, chronic kidney disease, decompensated liver disease: <b>bilateral</b> edema. Drug edema: calcium channel blockers, nonsteroidal anti-inflammatory drugs, thiazolidinediones. Lymphedema: unilateral, no varicosities. Lipedema: bilateral symmetric, just above the ankles, women. Other ulcers: diabetic neuropathic, arterial, autoimmune, sickle cell anemia, erythema induratum. Punch biopsy if unsure.","s":2},{"t":"Work-up","d":"<b>Venous duplex ultrasound first</b>: patency (clot?) and valvular competence (reflux?). <b>★ Arterial pulse examination and ankle-brachial index</b> for any leg wound and older patients: not to diagnose the venous disease but to <b>rule out peripheral artery disease before compression</b>. Cross-sectional venography if ultrasound falls short; catheter venography (gold standard) only before an intervention.","s":2},{"t":"Management","d":"<b>Always nonoperative first.</b> Feet elevated <b>ABOVE heart level</b>; daily walking and ankle flexion; skin care with emollients (mid-potency topical corticosteroid for stasis dermatitis); <b>★ compression = standard treatment, graduated (tightest at the ankle)</b>; cellulitis: oral antibiotics (cephalexin or clindamycin). Ulcers need edema control and compression, wound care referral, <b>4&ndash;6 months</b> to heal. No oral drug proven; surgery occludes or removes vessels.","s":2},{"t":"Refer to vascular","d":"<b>Arterial insufficiency (same-day)</b>; nonhealing ulcers; recurrent ulcers; persistent stasis dermatitis; suspected contact dermatitis; diagnostic doubt; significant saphenous reflux; long-term edema control.","s":2},{"t":"What","d":"Dilated, tortuous superficial veins from <b>venous reflux and venous hypertension</b>; most commonly the <b>great saphenous vein</b>, also the short saphenous vein.","s":3},{"t":"Risk factors","d":"<b>★ Family history = the most common predisposing factor.</b> Prolonged standing or heavy lifting; women after pregnancy.","s":3},{"t":"Symptoms","d":"<b>★ Dull, achy heaviness or fatigue brought on by standing = the most common symptom.</b> Itching above the ankle or over the veins; may be asymptomatic. Long-standing varicose veins can progress to chronic venous insufficiency.","s":3},{"t":"Exam","d":"Dilated, tortuous, palpable veins of the thigh and calf, seen standing; may be tender.","s":3},{"t":"Diagnosis","d":"<b>Clinical</b>: examine the leg in a dependent position. Venous duplex (Doppler) ultrasound confirms and maps the extent of reflux.","s":3},{"t":"Management","d":"Isolated varicose veins: elevation, exercise, compression, <b>rule out arterial disease before compression</b>; stockings for weeks to months before ablation. Goal = symptoms and appearance; they often recur. Procedures: <b>sclerotherapy</b>, vein stripping, laser or radiofrequency catheter.","s":3},{"t":"Definitions","d":"<b>Phlebitis</b> = inflammation of the vein wall <b>without</b> thrombus. <b>Thrombophlebitis</b> = phlebitis <b>with</b> thrombus. Told apart because treatment differs.","s":4},{"t":"Risk factors","d":"<b>Varicose veins = the most common cause in the lower extremity.</b> <b>Recent intravenous catheter use (peripherally inserted central catheter most common) = the most common cause in the upper extremity.</b> Inactivity; local trauma or procedure on superficial veins; pregnancy or estrogen; malignancy or hypercoagulable state; prior superficial vein thrombosis without varicose veins.","s":4},{"t":"Presentation","d":"Tenderness, pain, induration and erythema along a superficial vein; an <b>indurated palpable cord</b> with warmth and erythema; you can trace the vein.","s":4},{"t":"Septic (suppurative)","d":"Infection within the vein: <b>high fever, fluctuance, purulent drainage</b>, or erythema extending well beyond the vein margin. Uncommon without prior venous cannulation, so ask about a recent intravenous line. The deck gives no treatment; a missed infection can leave the patient septic.","s":4},{"t":"Diagnosis","d":"History and examination, confirmed by <b>venous duplex ultrasound (gold standard)</b>: noncompressible superficial vein with wall thickening. Wall thickening alone = phlebitis; with a clot inside = thrombophlebitis.","s":4},{"t":"★ Treatment","d":"<b>Nonsteroidal anti-inflammatory drugs first</b> (ibuprofen, diclofenac), warm compresses, compression, elevation. <b>Anticoagulation only for extensive clot burden</b> or intermediate or higher thrombosis risk (unfractionated heparin, enoxaparin, fondaparinux). Repeat examination in <b>7&ndash;10 days</b>; repeat duplex ultrasound if signs persist or worsen.","s":4},{"t":"Prognosis","d":"Rarely causes serious complications; <b>rarely embolizes</b>. Counsel: patients worry it is a clot.","s":4},{"t":"What","d":"Abnormal artery-to-vein connection that <b>bypasses the capillary bed</b>; created (hemodialysis), acquired (iatrogenic, trauma) or congenital.","s":5},{"t":"Created (dialysis)","d":"<b>★ Upper extremity fistulas are the ones most commonly created for hemodialysis access</b> (upper arm or forearm, preferred over the leg). Healthy: <b>diffuse thrill and soft bruit</b>, both systolic and diastolic; <b>collapses completely on arm elevation</b>. <b>Cannot hear a bruit: refer.</b>","s":5},{"t":"Acquired (iatrogenic)","d":"Most common in the <b>lower extremity</b>, the <b>femoral vessels</b>, after groin access for percutaneous procedures such as cardiac catheterization. Examine the puncture site with a complete lower extremity vascular examination; compare pulses with the pre-procedure pulses.","s":5},{"t":"Diagnosis","d":"Physical examination; <b>duplex ultrasound</b> confirms a suspected iatrogenic fistula; computed tomography angiography or angiography gives location and size.","s":5},{"t":"Nicoladoni-Branham sign","d":"Compressing a large fistula <b>slows the heart rate</b> (reflex). Do not hold the fistula closed to demonstrate it on a patient.","s":5},{"t":"Complications","d":"Watch for infection, chronic venous insufficiency, heart failure and ischemia.","s":5},{"t":"Management","d":"<b>Acquired:</b> surgical, remove the fistula or decrease its size. <b>Congenital:</b> hard to treat (many communications); elastic support hose, sometimes embolization. Primary care: keep it free of infection, decide congenital versus acquired, find out how, refer.","s":5},{"t":"Who","d":"Older than <b>60</b> with no other risk factors, or <b>50 with risk factors</b>; males &gt; females; <b>half also have coronary artery disease</b>. Smoking = <b>three times</b> the risk; elevated homocysteine = earlier atherosclerosis.","s":6},{"t":"Claudication","d":"Activity pain relieved by rest in <b>about 10 minutes</b>, analogous to angina. <b>Site = level:</b> buttock/hip = aortoiliac; thigh = common femoral; <b>upper two-thirds of calf = superficial femoral (most common)</b>; lower third of calf = popliteal; foot = tibial/peroneal.","s":6},{"t":"Leriche triad","d":"Claudication + <b>absent or diminished femoral pulses</b> + <b>erectile dysfunction</b> (aortoiliac).","s":6},{"t":"Exam","d":"Dry, thin, shiny skin; hair and nail loss; atrophy; cool limb (temperature line &asymp; level); pulses gone <b>below</b> the stenosis; capillary refill &gt; 2 s; bruits. <b>Buerger:</b> leg up 45&deg; for 1 minute &rarr; <b>pallor</b>; dangle &rarr; <b>dependent rubor</b>. Darker skin: use temperature, texture, capillary refill.","s":6},{"t":"Ankle-brachial index","d":"Initial bedside test. Higher ankle &divide; higher arm; the <b>lower leg</b> is the overall index. <b>0.9&ndash;1.3</b> normal &middot; <b>0.4&ndash;0.9</b> claudication &middot; <b>0&ndash;0.4</b> rest pain / tissue loss &middot; <b>&gt; 1.3 abnormal</b> (calcified, non-compressible &mdash; diabetes).","s":6},{"t":"Imaging","d":"<b>Duplex ultrasound</b> = mainstay initial imaging (no contrast, no radiation). Computed tomography angiography: no with contrast allergy or poor renal function. Magnetic resonance angiography: the contrast-allergy alternative; no with pacemaker or intracranial aneurysm clips. <b>Conventional angiography = gold standard</b>, used to guide intervention.","s":6},{"t":"Treatment","d":"Stop smoking; blood pressure &lt; 140/90 (&lt; 130/80 diabetes or renal failure); diabetes and weight control; <b>supervised exercise</b> (beats home-based) 30&ndash;45 min &times;3/week. Aspirin, clopidogrel, <b>cilostazol</b>; simvastatin or pravastatin (low-density lipoprotein &lt; 100, &lt; 70 high risk); pentoxifylline; folic acid + B12 + B6 for high homocysteine.","s":6},{"t":"Revascularize when","d":"Disabling claudication despite exercise and drugs: angioplasty &plusmn; stent, atherectomy; <b>bypass (saphenous vein or synthetic) mainly for critical limb ischemia</b>; endarterectomy; amputation.","s":6},{"t":"Rest pain","d":"Constant, burning, forefoot and toes, <b>worse elevated or reclining</b>, wakes at night, narcotics fail. <b>Relieved by dangling the leg or walking</b> (the paradox).","s":7},{"t":"Ulcers &amp; gangrene","d":"Ulcers at toe tips, between digits, metatarsal heads: <b>dry, punched out, painful, little bleeding</b>; osteomyelitis risk. <b>Dry gangrene</b>: hard, clear demarcation. <b>Wet gangrene = surgical emergency</b> (moist, edema, blisters, clostridial gas, sepsis).","s":7},{"t":"Acute limb ischemia","d":"<b>Sudden occlusion of a previously patent artery &mdash; vascular emergency.</b> Emboli: heart is the source in <b>80&ndash;90%</b> (atrial fibrillation, post-infarct ventricular thrombus). Six P&rsquo;s: pain, pallor, pulselessness, paresthesia, paralysis, poikilothermia. <b>Earliest neurologic sign: sensory loss over the dorsum of the foot.</b>","s":7},{"t":"Rutherford","d":"<b>I</b> viable &middot; <b>IIA</b> salvageable if prompt (no sensory loss, no weakness) &middot; <b>IIB</b> salvageable only with immediate revascularization &rarr; surgical suite &middot; <b>III</b> irreversible &rarr; major amputation, no imaging needed. (IIA arterial Doppler: slides disagree.)","s":7},{"t":"Treat","d":"<b>Immediate vascular surgery consult</b> + <b>intravenous heparin</b>; catheter-directed thrombolysis (alteplase) if <b>&lt; 14 days</b>; thromboembolectomy; bypass; amputation.","s":7},{"t":"Blue toe","d":"Atheroembolism (cholesterol, fibrin, platelets from proximal plaque): painful blue toe, livedo reticularis &mdash; <b>distal pulses still palpable</b>.","s":7},{"t":"Why it matters","d":"<b>80% of new noncardioembolic strokes</b>; strokes mostly from <b>plaque rupture</b>. Asymptomatic outnumber symptomatic <b>4:1</b>.","s":8},{"t":"Symptoms","d":"Transient ischemic attack (&lt; 24 h), stroke, <b>amaurosis fugax</b> (monocular blindness like a curtain descending). Auscultate each carotid separately, breath held.","s":8},{"t":"Tests","d":"<b>Duplex ultrasonography</b> = initial screening and follow-up. Computed tomography / magnetic resonance angiography. <b>Digital subtraction angiography = gold standard</b>, not for screening. <b>Do not screen asymptomatic adults.</b>","s":8},{"t":"Treat","d":"&lt; 50%: medical (antiplatelets, blood pressure, glucose, statins, <b>stop smoking &mdash; nearly doubles stroke risk</b>). Surgery: <b>symptomatic &gt; 70%</b> or <b>asymptomatic &gt; 80% with life expectancy &gt; 5 years</b>. <b>Endarterectomy = gold standard</b> (stroke or nerve damage); stenting for poor surgical candidates.","s":8},{"t":"Definition","d":"Dilation &gt; <b>50%</b> of normal. Infrarenal aorta 2 cm; <b>&gt; 3 cm = aneurysm</b>; <b>90% infrarenal</b>. True = all three layers (saccular or fusiform).","s":9},{"t":"Abdominal: risk","d":"<b>Smoking ever = strongest</b>; male (2:1 under 80, 1:1 over 80); age; Caucasian; atherosclerosis; hypertension; family history; other aneurysms. <b>Protective: female, non-Caucasian, diabetes</b> (but women rupture more). 15,000 deaths/year.","s":9},{"t":"Abdominal: signs","d":"Mostly incidental. Expansion pain (hypogastrium, back, flank, groin), early satiety, blue toe. <b>Rupture triad (50%): pain + pulsatile mass (virtually diagnostic) + hypotension</b>; Grey Turner sign (flank ecchymosis). Bruit nonspecific.","s":9},{"t":"Abdominal: tests","d":"<b>Ultrasound = initial screening</b> and serial size. X-ray calcified outline 75%. <b>Computed tomography angiography = best diagnostic and planning study.</b> Magnetic resonance imaging for stable dye-allergic patients. Type and crossmatch.","s":9},{"t":"Abdominal: sizes","d":"3.0&ndash;3.9 cm ultrasound <b>every 3 years</b>; 4.0&ndash;5.4 cm <b>every 6&ndash;12 months</b>. Specialist at <b>4.5 cm</b>; urgent for pain at any size. <b>Repair: &ge; 5.0 cm women, &gt; 5.5 cm men, or 0.5 cm growth in 6 months.</b> Rupture rare &lt; 5 cm.","s":9},{"t":"Abdominal: treat","d":"Stop smoking, aggressive blood pressure control, moderate exercise. Endovascular or open repair. Symptomatic unruptured: large-bore lines, pain and blood pressure control (beta blocker), repair. <b>Ruptured: surgical emergency</b> &mdash; large-bore lines, type and crossmatch.","s":9},{"t":"Thoracic","d":"Hypertension common; mostly incidental on chest X-ray (<b>widened mediastinum</b>). Ascending &rarr; aortic regurgitation, heart failure; <b>arch &rarr; hoarseness</b>; descending &rarr; dysphagia, stridor, cough. <b>Computed tomography angiography most used.</b> Beta blockers, blood pressure control; urgent imaging for pain. <b>Repair all symptomatic</b>; ascending &gt; 5.5, descending &gt; 6.0 cm, growth &gt; 0.5 cm/<b>year</b>.","s":9},{"t":"Pseudoaneurysm","d":"Blood outside the wall after arterial rupture &mdash; <b>femoral artery after catheterization</b>. Thin wall, irregular, hematoma. <b>&lt; 2 cm watch</b>; ultrasound-guided <b>thrombin injection</b>.","s":9},{"t":"Dissection","d":"Intimal tear &rarr; false lumen in the media. 60s&ndash;70s (younger in <b>Marfan</b>), male, <b>hypertension</b>. <b>Sudden tearing chest pain</b> that moves; syncope; aortic regurgitation. Electrocardiogram may be normal; <b>computed tomography chest and abdomen</b>. <b>Systolic 100&ndash;120 mmHg with esmolol or nitroprusside</b>; surgery; high untreated mortality.","s":9},{"t":"★ His study instruction","d":"At the close (2:07:05): study the <b>numbers, genes, most likely causes, best diagnostics and gold standards</b>. Take-home (2:07:26): cardiomyopathy is disease of the <b>muscle itself</b>; sort every case into dilated, hypertrophic or restrictive and decide <b>genetic versus secondary</b>.","s":10},{"t":"★ Best test","d":"<b>Dilated:</b> echocardiogram is definitive: thin dilated walls, ejection fraction &lt; 40% (58:27). <b>Myocarditis:</b> endomyocardial biopsy = <b>gold standard</b> even though rarely done (1:26:09); gadolinium magnetic resonance imaging shows the extent of inflammation (1:25:53). <b>Hypertrophic:</b> echocardiogram is the test of choice (1:38:54); <b>systolic anterior motion</b> is the telltale sign of obstruction (1:31:24). <b>Restrictive:</b> echocardiogram can look normal, so step to magnetic resonance imaging (1:58:21). <b>Takotsubo:</b> mid and apical hypokinesis or akinesis (2:02:41).","s":10},{"t":"★ Numbers he read","d":"<b>Dilated:</b> 10,000 deaths and 46,000 hospitalizations a year; ages 20&ndash;60; familial up to 35%; ejection fraction &lt; 40%; defibrillator at &lt; 35% on optimized therapy; 50% dead at 5 years once symptomatic. <b>Myocarditis:</b> viral = 20% of dilated cardiomyopathy; one third later develop it. <b>Hypertrophic:</b> 1 in 500; at least 1,500 mutations; &gt; 80% of sudden deaths are ventricular fibrillation; wall 1.5 cm or more. <b>Takotsubo:</b> 90% postmenopausal women.","s":10},{"t":"★ Can't miss, and what he stressed","d":"<b>Can't miss:</b> hypertrophic cardiomyopathy, so syncope, especially in a young athlete, needs a work-up (1:33:35). <b>Stressed:</b> family history is &ldquo;extremely important&rdquo;, primary relatives first (51:26); alcohol is one of the few causes of dilated cardiomyopathy that can recover (47:50); constrictive pericarditis must be differentiated from restrictive cardiomyopathy (1:56:11).","s":10},{"t":"★ Exercise (his last answer)","d":"Obstructive hypertrophic cardiomyopathy: no strenuous activity until it is worked up (2:10:39). The slide advice is mild to moderate, <b>noncompetitive</b> activity: do not key &ldquo;no exercise at all&rdquo;. Heart failure from other causes: be active (2:11:00).","s":10},{"t":"★ Recording vs slide","d":"<b>Normal electrocardiogram in dilated cardiomyopathy:</b> slide says it &ldquo;almost rules it out&rdquo;; he said it does not (57:56). Truth: unlikely, not excluded. <b>Hypertrophic:</b> nitrates and positive inotropes avoided; diuretics only with care (he said stay away). Amiodarone is an adjunct; the defibrillator is the proven sudden-death device.","s":10},{"t":"★ What","d":"<b>Most common</b> cardiomyopathy: dilated, poorly contracting ventricle(s) <b>without</b> severe coronary disease or pressure/volume overload &rarr; systolic failure, globular heart; mitral (early) and tricuspid regurgitation.","s":11},{"t":"★ Who / why","d":"Ages 20&ndash;60, male, high in African Americans. Idiopathic; <b>familial up to 35%</b> (autosomal dominant); viral or Chagas myocarditis; chemotherapy; <b>alcohol (can recover if stopped; 47:50)</b>; thiamine deficiency; lupus, rheumatoid arthritis; <b>peripartum</b> (last trimester to 6 months after delivery). Idiopathic = main indication for transplant.","s":11},{"t":"Signs","d":"Progressive exertional dyspnea, orthopnea, paroxysmal nocturnal dyspnea, edema; <b>laterally displaced impulse, third heart sound</b>, regurgitant murmurs, narrow pulse pressure, jugular distension, hepatojugular reflux.","s":11},{"t":"★ Tests","d":"Electrocardiogram usually abnormal; a normal one makes it unlikely but does not exclude it (slide 37: &ldquo;will almost rule out&rdquo;; Carter: &ldquo;doesn&rsquo;t rule out anything&rdquo;, 57:56). Echo = <b>definitive</b>: <b>dilated thin walls</b>, ejection fraction &lt; 40% (58:27). X-ray: cardiomegaly, Kerley B lines. B-type natriuretic peptide &lt; 100 pg/mL excludes heart failure. Magnetic resonance imaging for inflammatory or infiltrative causes; biopsy rarely.","s":11},{"t":"★ Treat","d":"As chronic heart failure: <b>every patient gets a beta blocker + angiotensin-converting enzyme inhibitor</b>; loop diuretics; spironolactone; sacubitril/valsartan. Anticoagulate only for atrial fibrillation, artificial valve or mural thrombus. <b>Defibrillator if ejection fraction &lt; 35% after maximal therapy (1:02:33)</b>; biventricular pacemaker; assist device (bridge or destination); transplant.","s":11},{"t":"★ Teach / outlook","d":"Remove the cause; <b>sodium &lt; 2 g/day</b>; genetic counseling if familial. <b>50% dead at 5 years once symptomatic (1:06:44).</b>","s":11},{"t":"Myocarditis: who","d":"Otherwise healthy, <b>young males</b>; <b>flulike illness 1&ndash;2 weeks before</b>; viral most frequent (Coxsackie B, parvovirus B19, human herpesvirus 6, COVID-19 (coronavirus disease 2019)...). Viral myocarditis = 20% of dilated cardiomyopathy.","s":12},{"t":"Myocarditis: picture","d":"New heart failure or cardiogenic shock with no prior heart disease; palpitations, syncope, sudden death (ventricular arrhythmia, heart block).","s":12},{"t":"★ Myocarditis: tests","d":"Troponin, leukocytosis, sedimentation rate, echo; angiography to exclude ischemia; <b>gadolinium magnetic resonance imaging</b> (best for the extent, 1:25:53). <b>Endomyocardial biopsy = gold standard</b> (1:26:09) once other causes are excluded, for unexplained deterioration not responding to treatment.","s":12},{"t":"★ Myocarditis: treat","d":"<b>Supportive care is the mainstay</b>; stabilize. Most mild cases recover; <b>one third later develop dilated cardiomyopathy</b> (1:21:57).","s":12},{"t":"★ Takotsubo","d":"<b>90% postmenopausal women</b> (2:01:12) after a big emotional or physical stressor; low cardiac risk. Mimics acute coronary syndrome: chest pain, dyspnea; troponin up; <b>ST elevation, T inversion</b>; echo <b>mid and apical hypokinesis</b>. <b>Confirmed by catheterization: normal coronaries.</b> Treat by the acute coronary syndrome protocol, <b>admit to cardiology</b> (2:03:16); beta blockers. <b>Most recover completely</b> (2:03:39).","s":12},{"t":"What / who","d":"Unexplained left ventricular hypertrophy, <b>asymmetric septal</b>. <b>Autosomal dominant</b> (sarcomere genes); <b>1 in 500</b>; male. <b>Leading cause of sudden death in preadolescents and adolescents</b> (extreme exertion; &gt; 80% ventricular fibrillation).","s":13},{"t":"★ Obstruction","d":"Septum narrows the outflow tract + <b>systolic anterior motion</b> of the anterior mitral leaflet &rarr; mid-systolic obstruction. Systolic anterior motion on echo = the telltale sign (1:31:24).","s":13},{"t":"★ Symptoms","d":"Dyspnea (commonest), palpitations, <b>exertional syncope / presyncope on standing = high sudden-death risk, urgent work-up</b> (1:33:35), angina without coronary disease.","s":13},{"t":"Signs","d":"Normal blood pressure and rate; <b>pulsus bisferiens</b> (double peak); forceful sustained apex; <b>fourth heart sound</b>. Crescendo-decrescendo murmur, left sternal border 3rd&ndash;4th space, to the suprasternal notch, <b>not the carotids</b>.","s":13},{"t":"Maneuvers","d":"<b>More blood in the heart = softer; less = louder.</b> Squat, leg raise, handgrip &rarr; softer. <b>Valsalva, standing</b>, amyl nitrite &rarr; louder. Breathing: no effect.","s":13},{"t":"★ Tests","d":"<b>Echocardiography = test of choice</b> (1:38:54): wall <b>&ge; 1.5 cm</b>, septal pattern, small cavity, ejection fraction normal (&gt; 75% late). Electrocardiogram: inferior and lateral Q waves, left axis deviation. Magnetic resonance imaging if echo questionable; 24&ndash;48 h ambulatory monitor; catheterization only before invasive therapy; genetic testing does not change treatment.","s":13},{"t":"★ Treat","d":"<b>Beta blocker first</b>, then verapamil or diltiazem. <b>AVOID nitrates, dehydrating diuretics, digoxin, epinephrine, norepinephrine</b> (1:43:49). Amiodarone (slide: reduces sudden death; an adjunct, see the Recording vs slide row), disopyramide, defibrillator; atrial fibrillation &rarr; anticoagulate. <b>Myectomy</b> or <b>alcohol septal ablation</b> (months to thin).","s":13},{"t":"★ Teach","d":"Mild to moderate <b>noncompetitive</b> activity (suspected obstructive disease: no strenuous activity until worked up, 2:10:39); <b>stay hydrated</b> (1:46:52); avoid excess alcohol. Sudden death = leading cause of death.","s":13},{"t":"★ What","d":"<b>Least common.</b> Stiff, normal-size ventricles; <b>big atria</b>, atrial fibrillation; ejection fraction preserved until late; <b>right-sided failure dominates</b>; heart block from nodal fibrosis. <b>Poorest prognosis</b> of all (1:59:32).","s":14},{"t":"★ Causes","d":"<b>Amyloidosis (most common in the United States; 1:50:28)</b>, hemochromatosis, sarcoidosis, <b>mediastinal radiation, chemotherapy</b>; idiopathic; genetic.","s":14},{"t":"★ Signs","d":"Late presentation; hepatomegaly, ascites, pedal edema; prefers sitting; raised jugular venous pressure; <b>Kussmaul sign</b> (jugular pressure <b>rises with inspiration</b>; 1:55:08); fourth heart sound if no regurgitation.","s":14},{"t":"★ Tests","d":"Electrocardiogram: <b>low QRS voltage in amyloid</b>. Echo: big atria, preserved function &mdash; <b>not definitive</b>, can look normal (1:58:01). <b>Cardiac magnetic resonance imaging separates it from constrictive pericarditis (pericardial thickening = pericarditis)</b>; <b>constrictive pericarditis must be differentiated</b> (1:56:11). Biopsy when all else is negative.","s":14},{"t":"Treat","d":"Treat the cause; <b>diuretics with caution (preload-dependent)</b>; beta blockers, verapamil or diltiazem; anticoagulate atrial thrombi; pacemaker for heart block; transplant.","s":14},{"t":"★ Populations","d":"<b>Adolescent:</b> genetic screening for hypertrophic cardiomyopathy, activity restriction if high risk (2:04:07). <b>Adult:</b> guideline-directed therapy, devices, sodium restriction, alcohol cessation, assist device or transplant. <b>Elderly:</b> tailored to frailty, <b>cautious diuretics and vasodilators</b>, symptom control (&ldquo;better days&rdquo;, 2:05:18), palliative discussions. Rehab and hospice referral in end-stage disease.","s":14}],"map":{"clinical-medicine-and-surgery-i-exam-5-arterial-occlusive-aneurysm-quiz-version-2":[81,74,-1,-1,65,81,-1,65,70,-1,-1,-1,-1,65,-1,-1,65,-1,65,80,-1,-1,-1,79,79,-1,-1,79,-1,-1],"clinical-medicine-and-surgery-i-exam-5-arterial-occlusive-aneurysm-quiz":[-1,79,63,65,-1,76,60,-1,81,60,81,-1,-1,-1,79,-1,81,-1,-1,65,58,-1,-1,-1,68,-1,-1,65,80,-1],"clinical-medicine-and-surgery-i-exam-5-arterial-occlusive-aneurysm-vignettes-version-2":[-1,65,59,65,76,65,-1,79,78,80,-1,-1,63,-1,-1,-1,79,65,80,81,-1,55,-1,-1,-1,81,81,79,60,-1],"clinical-medicine-and-surgery-i-exam-5-arterial-occlusive-aneurysm-vignettes":[65,80,65,81,60,79,59,65,-1,-1,81,57,-1,-1,-1,68,78,63,-1,-1,80,-1,81,-1,79,65,-1,60,64,-1],"clinical-medicine-and-surgery-i-exam-5-cardiomyopathy-quiz-version-2":[94,-1,-1,85,98,-1,97,-1,-1,96,-1,98,-1,-1,-1,-1,-1,100,-1,88,-1,83,-1,-1,-1,-1,-1,-1,112,112],"clinical-medicine-and-surgery-i-exam-5-cardiomyopathy-quiz":[112,94,-1,112,-1,-1,-1,-1,-1,-1,-1,97,97,-1,-1,-1,95,97,-1,-1,-1,-1,-1,97,-1,98,-1,-1,39,-1],"clinical-medicine-and-surgery-i-exam-5-cardiomyopathy-vignettes-version-2":[95,94,-1,-1,-1,83,98,-1,97,-1,-1,-1,112,-1,99,-1,-1,-1,-1,-1,-1,-1,110,112,-1,100,-1,-1,112,88],"clinical-medicine-and-surgery-i-exam-5-cardiomyopathy-vignettes":[98,-1,-1,-1,47,96,-1,97,94,-1,-1,98,109,-1,110,-1,-1,112,-1,-1,-1,92,-1,-1,-1,88,-1,98,-1,112],"clinical-medicine-and-surgery-i-exam-5-venous-disorders-quiz-version-2":[-1,42,21,-1,14,44,7,13,-1,12,28,15,25,45,6,0,0,-1,-1,13,-1,51,2,33,11,46,11,11,9,12],"clinical-medicine-and-surgery-i-exam-5-venous-disorders-quiz":[15,5,49,-1,11,54,15,25,-1,45,12,-1,-1,11,44,-1,20,11,32,-1,42,40,-1,46,24,-1,0,27,0,11],"clinical-medicine-and-surgery-i-exam-5-venous-disorders-vignettes-version-2":[49,-1,31,11,42,45,6,11,-1,-1,-1,59,49,-1,45,-1,51,45,0,-1,-1,50,-1,37,0,6,16,-1,15,-1],"clinical-medicine-and-surgery-i-exam-5-venous-disorders-vignettes":[40,21,12,23,54,35,22,59,20,42,7,2,26,42,15,6,8,52,5,0,6,11,46,30,54,-1,-1,-1,40,24]}};
